-- WP15: directional MESH account mapping, masked bank projection, and independent NEON remittance verification.
BEGIN;
DO $$ BEGIN IF current_database()<>'athyper_neon' THEN RAISE EXCEPTION 'WP15 NEON account/bank linkage must target athyper_neon'; END IF; END $$;

CREATE TABLE control.mesh_business_partner_account_link(id uuid NOT NULL DEFAULT shared.uuidv7(),tenant_id uuid NOT NULL,profile_projection_id uuid NOT NULL,source_tenant_id uuid NOT NULL,source_network_account_id uuid NOT NULL,recipient_network_account_id uuid NOT NULL,network_relationship_id uuid NOT NULL,business_partner_id uuid NOT NULL,proposed_role master.partner_role_d NOT NULL,external_reference_id uuid,onboarding_request_id uuid,idempotency_key text NOT NULL,decision_fingerprint text,status text NOT NULL DEFAULT 'pending_approval',reviewed_at timestamptz,reviewed_by uuid,approved_at timestamptz,approved_by uuid,terminated_at timestamptz,terminated_by uuid,termination_reason text,row_version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz,updated_by uuid,CONSTRAINT mesh_bp_account_link_pkey PRIMARY KEY(id),CONSTRAINT mesh_bp_account_link_tenant_id_uq UNIQUE(tenant_id,id),CONSTRAINT mesh_bp_account_link_idempotency_uq UNIQUE(tenant_id,idempotency_key),CONSTRAINT mesh_bp_account_link_coordinate_uq UNIQUE(tenant_id,source_tenant_id,source_network_account_id),CONSTRAINT mesh_bp_account_link_status_chk CHECK(status IN('pending_approval','active','rejected','terminated','corrected')),CONSTRAINT mesh_bp_account_link_key_chk CHECK(length(idempotency_key) BETWEEN 8 AND 200),CONSTRAINT mesh_bp_account_link_decision_chk CHECK((status='pending_approval' AND decision_fingerprint IS NULL AND reviewed_at IS NULL AND reviewed_by IS NULL AND approved_at IS NULL AND approved_by IS NULL AND external_reference_id IS NULL)OR(status='rejected' AND decision_fingerprint~'^[a-f0-9]{64}$' AND reviewed_at IS NOT NULL AND reviewed_by IS NOT NULL AND approved_at IS NULL AND approved_by IS NULL AND external_reference_id IS NULL)OR(status IN('active','terminated','corrected') AND decision_fingerprint~'^[a-f0-9]{64}$' AND reviewed_at IS NOT NULL AND reviewed_by IS NOT NULL AND approved_at IS NOT NULL AND approved_by IS NOT NULL AND external_reference_id IS NOT NULL)),CONSTRAINT mesh_bp_account_link_sod_chk CHECK(approved_by IS NULL OR approved_by IS DISTINCT FROM created_by),CONSTRAINT mesh_bp_account_link_termination_chk CHECK((terminated_at IS NULL AND terminated_by IS NULL AND termination_reason IS NULL)OR(terminated_at IS NOT NULL AND terminated_by IS NOT NULL AND nullif(btrim(termination_reason),'') IS NOT NULL)),CONSTRAINT mesh_bp_account_link_version_chk CHECK(row_version>=1),CONSTRAINT mesh_bp_account_link_audit_pair_chk CHECK((updated_at IS NULL)=(updated_by IS NULL)),CONSTRAINT mesh_bp_account_link_tenant_fk FOREIGN KEY(tenant_id) REFERENCES master.tenant(id),CONSTRAINT mesh_bp_account_link_projection_fk FOREIGN KEY(tenant_id,profile_projection_id) REFERENCES control.mesh_business_partner_profile_projection(tenant_id,id),CONSTRAINT mesh_bp_account_link_partner_fk FOREIGN KEY(tenant_id,business_partner_id) REFERENCES master.business_partner(tenant_id,id),CONSTRAINT mesh_bp_account_link_external_fk FOREIGN KEY(tenant_id,external_reference_id) REFERENCES master.external_reference(tenant_id,id),CONSTRAINT mesh_bp_account_link_request_fk FOREIGN KEY(tenant_id,onboarding_request_id) REFERENCES document.business_partner_request(tenant_id,id),CONSTRAINT mesh_bp_account_link_created_by_fk FOREIGN KEY(tenant_id,created_by) REFERENCES master.principal(tenant_id,id),CONSTRAINT mesh_bp_account_link_reviewed_by_fk FOREIGN KEY(tenant_id,reviewed_by) REFERENCES master.principal(tenant_id,id),CONSTRAINT mesh_bp_account_link_approved_by_fk FOREIGN KEY(tenant_id,approved_by) REFERENCES master.principal(tenant_id,id),CONSTRAINT mesh_bp_account_link_terminated_by_fk FOREIGN KEY(tenant_id,terminated_by) REFERENCES master.principal(tenant_id,id));

CREATE TABLE control.mesh_bank_account_disclosure_inbox(id uuid NOT NULL DEFAULT shared.uuidv7(),tenant_id uuid NOT NULL,event_id uuid NOT NULL,source_tenant_id uuid NOT NULL,source_network_account_id uuid NOT NULL,recipient_network_account_id uuid NOT NULL,network_relationship_id uuid NOT NULL,disclosure_id uuid NOT NULL,disclosure_version integer NOT NULL,lifecycle_version integer NOT NULL,event_type text NOT NULL,payload_hash text NOT NULL,envelope_json jsonb NOT NULL,envelope_hash text NOT NULL,occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),received_by uuid NOT NULL,CONSTRAINT mesh_bank_disclosure_inbox_pkey PRIMARY KEY(id),CONSTRAINT mesh_bank_disclosure_inbox_tenant_id_uq UNIQUE(tenant_id,id),CONSTRAINT mesh_bank_disclosure_inbox_event_uq UNIQUE(tenant_id,event_id),CONSTRAINT mesh_bank_disclosure_inbox_parties_chk CHECK(tenant_id<>source_tenant_id),CONSTRAINT mesh_bank_disclosure_inbox_type_chk CHECK(event_type IN('mesh.bank_account.disclosed','mesh.bank_account.changed','mesh.bank_account.revoked')),CONSTRAINT mesh_bank_disclosure_inbox_version_chk CHECK(disclosure_version>=1 AND lifecycle_version>=1),CONSTRAINT mesh_bank_disclosure_inbox_hash_chk CHECK(payload_hash~'^[a-f0-9]{64}$' AND envelope_hash~'^[a-f0-9]{64}$'),CONSTRAINT mesh_bank_disclosure_inbox_payload_chk CHECK(jsonb_typeof(envelope_json)='object' AND pg_column_size(envelope_json)<=65536),CONSTRAINT mesh_bank_disclosure_inbox_tenant_fk FOREIGN KEY(tenant_id) REFERENCES master.tenant(id),CONSTRAINT mesh_bank_disclosure_inbox_actor_fk FOREIGN KEY(tenant_id,received_by) REFERENCES master.principal(tenant_id,id));

CREATE TABLE snapshot.mesh_bank_account_disclosure_received(id uuid NOT NULL DEFAULT shared.uuidv7(),tenant_id uuid NOT NULL,inbox_event_id uuid NOT NULL,source_tenant_id uuid NOT NULL,network_relationship_id uuid NOT NULL,disclosure_id uuid NOT NULL,disclosure_version integer NOT NULL,lifecycle_version integer NOT NULL,payload_json jsonb NOT NULL,payload_hash text NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),received_by uuid NOT NULL,CONSTRAINT mesh_bank_disclosure_received_pkey PRIMARY KEY(id),CONSTRAINT mesh_bank_disclosure_received_tenant_id_uq UNIQUE(tenant_id,id),CONSTRAINT mesh_bank_disclosure_received_inbox_uq UNIQUE(tenant_id,inbox_event_id),CONSTRAINT mesh_bank_disclosure_received_version_chk CHECK(disclosure_version>=1 AND lifecycle_version>=1),CONSTRAINT mesh_bank_disclosure_received_payload_chk CHECK(jsonb_typeof(payload_json)='object' AND pg_column_size(payload_json)<=32768),CONSTRAINT mesh_bank_disclosure_received_hash_chk CHECK(payload_hash~'^[a-f0-9]{64}$'),CONSTRAINT mesh_bank_disclosure_received_tenant_fk FOREIGN KEY(tenant_id) REFERENCES master.tenant(id),CONSTRAINT mesh_bank_disclosure_received_inbox_fk FOREIGN KEY(tenant_id,inbox_event_id) REFERENCES control.mesh_bank_account_disclosure_inbox(tenant_id,id),CONSTRAINT mesh_bank_disclosure_received_actor_fk FOREIGN KEY(tenant_id,received_by) REFERENCES master.principal(tenant_id,id));

CREATE TABLE control.mesh_bank_account_projection(id uuid NOT NULL DEFAULT shared.uuidv7(),tenant_id uuid NOT NULL,account_link_id uuid NOT NULL,source_tenant_id uuid NOT NULL,source_network_account_id uuid NOT NULL,recipient_network_account_id uuid NOT NULL,network_relationship_id uuid NOT NULL,current_disclosure_id uuid NOT NULL,current_disclosure_version integer NOT NULL,current_lifecycle_version integer NOT NULL,current_snapshot_id uuid NOT NULL,last_inbox_event_id uuid NOT NULL,account_fingerprint text NOT NULL,projection_status text NOT NULL DEFAULT 'available',updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_by uuid NOT NULL,CONSTRAINT mesh_bank_account_projection_pkey PRIMARY KEY(id),CONSTRAINT mesh_bank_account_projection_tenant_id_uq UNIQUE(tenant_id,id),CONSTRAINT mesh_bank_account_projection_relationship_uq UNIQUE(tenant_id,network_relationship_id),CONSTRAINT mesh_bank_account_projection_version_chk CHECK(current_disclosure_version>=1 AND current_lifecycle_version>=1),CONSTRAINT mesh_bank_account_projection_fingerprint_chk CHECK(account_fingerprint~'^[a-f0-9]{64}$'),CONSTRAINT mesh_bank_account_projection_status_chk CHECK(projection_status IN('available','change_pending','verified','linked','revoked','expired','quarantined')),CONSTRAINT mesh_bank_account_projection_tenant_fk FOREIGN KEY(tenant_id) REFERENCES master.tenant(id),CONSTRAINT mesh_bank_account_projection_link_fk FOREIGN KEY(tenant_id,account_link_id) REFERENCES control.mesh_business_partner_account_link(tenant_id,id),CONSTRAINT mesh_bank_account_projection_snapshot_fk FOREIGN KEY(tenant_id,current_snapshot_id) REFERENCES snapshot.mesh_bank_account_disclosure_received(tenant_id,id),CONSTRAINT mesh_bank_account_projection_inbox_fk FOREIGN KEY(tenant_id,last_inbox_event_id) REFERENCES control.mesh_bank_account_disclosure_inbox(tenant_id,id),CONSTRAINT mesh_bank_account_projection_actor_fk FOREIGN KEY(tenant_id,updated_by) REFERENCES master.principal(tenant_id,id));

CREATE TABLE document.business_partner_bank_verification(id uuid NOT NULL DEFAULT shared.uuidv7(),tenant_id uuid NOT NULL,bank_projection_id uuid NOT NULL,business_partner_id uuid NOT NULL,supplier_company_profile_id uuid NOT NULL,company_code_id uuid NOT NULL,candidate_bank_account_link_id uuid,prior_bank_account_link_id uuid,expected_account_fingerprint text NOT NULL,verification_method text,verification_evidence jsonb NOT NULL DEFAULT '{}',idempotency_key text NOT NULL,decision_fingerprint text,application_fingerprint text,status text NOT NULL DEFAULT 'pending_verification',verified_at timestamptz,verified_by uuid,rejected_at timestamptz,rejected_by uuid,rejection_reason text,applied_at timestamptz,applied_by uuid,row_version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz,updated_by uuid,CONSTRAINT business_partner_bank_verification_pkey PRIMARY KEY(id),CONSTRAINT business_partner_bank_verification_tenant_id_uq UNIQUE(tenant_id,id),CONSTRAINT business_partner_bank_verification_idempotency_uq UNIQUE(tenant_id,idempotency_key),CONSTRAINT business_partner_bank_verification_status_chk CHECK(status IN('pending_verification','verified','rejected','applied','superseded')),CONSTRAINT business_partner_bank_verification_fingerprint_chk CHECK(expected_account_fingerprint~'^[a-f0-9]{64}$' AND(decision_fingerprint IS NULL OR decision_fingerprint~'^[a-f0-9]{64}$')AND(application_fingerprint IS NULL OR application_fingerprint~'^[a-f0-9]{64}$')),CONSTRAINT business_partner_bank_verification_key_chk CHECK(length(idempotency_key) BETWEEN 8 AND 200),CONSTRAINT business_partner_bank_verification_evidence_chk CHECK(jsonb_typeof(verification_evidence)='object' AND pg_column_size(verification_evidence)<=65536),CONSTRAINT business_partner_bank_verification_decision_chk CHECK((status='pending_verification' AND candidate_bank_account_link_id IS NULL AND decision_fingerprint IS NULL AND verified_at IS NULL AND verified_by IS NULL AND rejected_at IS NULL AND rejected_by IS NULL)OR(status='verified' AND candidate_bank_account_link_id IS NOT NULL AND nullif(btrim(verification_method),'') IS NOT NULL AND verification_evidence<>'{}' AND decision_fingerprint IS NOT NULL AND verified_at IS NOT NULL AND verified_by IS NOT NULL)OR(status='rejected' AND decision_fingerprint IS NOT NULL AND rejected_at IS NOT NULL AND rejected_by IS NOT NULL AND nullif(btrim(rejection_reason),'') IS NOT NULL)OR(status IN('applied','superseded') AND candidate_bank_account_link_id IS NOT NULL AND decision_fingerprint IS NOT NULL AND verified_at IS NOT NULL AND verified_by IS NOT NULL)),CONSTRAINT business_partner_bank_verification_sod_chk CHECK(verified_by IS NULL OR verified_by IS DISTINCT FROM created_by),CONSTRAINT business_partner_bank_verification_apply_chk CHECK((status='applied')=(application_fingerprint IS NOT NULL AND applied_at IS NOT NULL AND applied_by IS NOT NULL)),CONSTRAINT business_partner_bank_verification_version_chk CHECK(row_version>=1),CONSTRAINT business_partner_bank_verification_audit_pair_chk CHECK((updated_at IS NULL)=(updated_by IS NULL)),CONSTRAINT business_partner_bank_verification_tenant_fk FOREIGN KEY(tenant_id) REFERENCES master.tenant(id),CONSTRAINT business_partner_bank_verification_projection_fk FOREIGN KEY(tenant_id,bank_projection_id) REFERENCES control.mesh_bank_account_projection(tenant_id,id),CONSTRAINT business_partner_bank_verification_partner_fk FOREIGN KEY(tenant_id,business_partner_id) REFERENCES master.business_partner(tenant_id,id),CONSTRAINT business_partner_bank_verification_profile_fk FOREIGN KEY(tenant_id,supplier_company_profile_id) REFERENCES master.company_code_supplier_profile(tenant_id,id),CONSTRAINT business_partner_bank_verification_company_fk FOREIGN KEY(tenant_id,company_code_id) REFERENCES master.company_code(tenant_id,id),CONSTRAINT business_partner_bank_verification_candidate_fk FOREIGN KEY(tenant_id,candidate_bank_account_link_id) REFERENCES master.bank_account_link(tenant_id,id),CONSTRAINT business_partner_bank_verification_prior_fk FOREIGN KEY(tenant_id,prior_bank_account_link_id) REFERENCES master.bank_account_link(tenant_id,id),CONSTRAINT business_partner_bank_verification_created_by_fk FOREIGN KEY(tenant_id,created_by) REFERENCES master.principal(tenant_id,id),CONSTRAINT business_partner_bank_verification_verified_by_fk FOREIGN KEY(tenant_id,verified_by) REFERENCES master.principal(tenant_id,id),CONSTRAINT business_partner_bank_verification_rejected_by_fk FOREIGN KEY(tenant_id,rejected_by) REFERENCES master.principal(tenant_id,id),CONSTRAINT business_partner_bank_verification_applied_by_fk FOREIGN KEY(tenant_id,applied_by) REFERENCES master.principal(tenant_id,id));

CREATE UNIQUE INDEX business_partner_bank_verification_open_uq ON document.business_partner_bank_verification(tenant_id,bank_projection_id,supplier_company_profile_id) WHERE status IN('pending_verification','verified');
CREATE INDEX mesh_bp_account_link_partner_idx ON control.mesh_business_partner_account_link(tenant_id,business_partner_id,status);CREATE INDEX mesh_bank_disclosure_inbox_relationship_idx ON control.mesh_bank_account_disclosure_inbox(tenant_id,network_relationship_id,received_at DESC);CREATE INDEX mesh_bank_account_projection_partner_idx ON control.mesh_bank_account_projection(tenant_id,account_link_id,projection_status);

CREATE OR REPLACE FUNCTION control.trg_reject_mesh_bank_disclosure_inbox_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'MESH bank disclosure inbox is immutable' USING ERRCODE='integrity_constraint_violation'; END $$;CREATE TRIGGER trg_mesh_bank_disclosure_inbox_immutable BEFORE UPDATE OR DELETE ON control.mesh_bank_account_disclosure_inbox FOR EACH ROW EXECUTE FUNCTION control.trg_reject_mesh_bank_disclosure_inbox_mutation();
CREATE OR REPLACE FUNCTION snapshot.trg_reject_mesh_bank_disclosure_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION 'MESH bank disclosure received snapshot is immutable' USING ERRCODE='integrity_constraint_violation'; END $$;CREATE TRIGGER trg_mesh_bank_disclosure_received_immutable BEFORE UPDATE OR DELETE ON snapshot.mesh_bank_account_disclosure_received FOR EACH ROW EXECUTE FUNCTION snapshot.trg_reject_mesh_bank_disclosure_mutation();

ALTER TABLE control.mesh_business_partner_account_link ENABLE ROW LEVEL SECURITY;ALTER TABLE control.mesh_business_partner_account_link FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_access ON control.mesh_business_partner_account_link USING(tenant_id=shared.current_tenant_id_soft()) WITH CHECK(tenant_id=shared.current_tenant_id());CREATE POLICY seed_write ON control.mesh_business_partner_account_link FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);
ALTER TABLE control.mesh_bank_account_disclosure_inbox ENABLE ROW LEVEL SECURITY;ALTER TABLE control.mesh_bank_account_disclosure_inbox FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_access ON control.mesh_bank_account_disclosure_inbox USING(tenant_id=shared.current_tenant_id_soft()) WITH CHECK(tenant_id=shared.current_tenant_id());CREATE POLICY seed_write ON control.mesh_bank_account_disclosure_inbox FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);
ALTER TABLE snapshot.mesh_bank_account_disclosure_received ENABLE ROW LEVEL SECURITY;ALTER TABLE snapshot.mesh_bank_account_disclosure_received FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_access ON snapshot.mesh_bank_account_disclosure_received USING(tenant_id=shared.current_tenant_id_soft()) WITH CHECK(tenant_id=shared.current_tenant_id());CREATE POLICY seed_write ON snapshot.mesh_bank_account_disclosure_received FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);
ALTER TABLE control.mesh_bank_account_projection ENABLE ROW LEVEL SECURITY;ALTER TABLE control.mesh_bank_account_projection FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_access ON control.mesh_bank_account_projection USING(tenant_id=shared.current_tenant_id_soft()) WITH CHECK(tenant_id=shared.current_tenant_id());CREATE POLICY seed_write ON control.mesh_bank_account_projection FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);
ALTER TABLE document.business_partner_bank_verification ENABLE ROW LEVEL SECURITY;ALTER TABLE document.business_partner_bank_verification FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_access ON document.business_partner_bank_verification USING(tenant_id=shared.current_tenant_id_soft()) WITH CHECK(tenant_id=shared.current_tenant_id());CREATE POLICY seed_write ON document.business_partner_bank_verification FOR ALL TO CURRENT_USER USING(true) WITH CHECK(true);

INSERT INTO authz.permission(id,canonical_code,permission_kind,module_id,risk_tier,requires_mfa,requires_sod,is_shareable,is_delegable,is_overridable,metadata,status,created_by) SELECT definition.id,definition.code,'entity_operation',module.id,definition.risk::authz.risk_tier_d,definition.mfa,definition.sod,false,false,false,'{"_seed":{"pack":"neon.mesh-account-bank-linkage","version":"1.0.0"}}','published','00000000-0000-0000-0000-000000000000' FROM control.module module CROSS JOIN(VALUES('43b1d1d7-9e31-5076-ab90-584063d732f5'::uuid,'neon.mesh_account_link.request','high',false,true),('285138d7-31c0-5506-a504-abfe00a13c87'::uuid,'neon.mesh_account_link.decide','critical',true,true),('1eb5268c-f686-5dc2-95db-333a1bdb1b32'::uuid,'neon.mesh_account_link.read','medium',false,false),('9c1966b9-9144-5186-b9bd-e51c668600ee'::uuid,'neon.mesh_bank_projection.receive','critical',true,false),('d8fdc899-fe16-5593-97a9-4206c643ef05'::uuid,'neon.business_partner_bank.verify','critical',true,true),('0d777b02-9325-5883-8b1a-775fa7f598b7'::uuid,'neon.business_partner_bank.apply','critical',true,true))definition(id,code,risk,mfa,sod) WHERE module.code='fnd' ON CONFLICT(canonical_code) DO UPDATE SET risk_tier=EXCLUDED.risk_tier,requires_mfa=EXCLUDED.requires_mfa,requires_sod=EXCLUDED.requires_sod,status='published';
INSERT INTO authz.permission_scope_kind(permission_id,scope_kind,propagation_mode,status,created_by) SELECT id,CASE WHEN canonical_code LIKE 'neon.business_partner_bank.%' THEN 'company_code'::authz.scope_kind_d ELSE 'network_relationship'::authz.scope_kind_d END,'exact','active','00000000-0000-0000-0000-000000000000' FROM authz.permission WHERE canonical_code LIKE 'neon.mesh_account_link.%' OR canonical_code LIKE 'neon.mesh_bank_projection.%' OR canonical_code LIKE 'neon.business_partner_bank.%' ON CONFLICT(permission_id,scope_kind,propagation_mode) DO UPDATE SET status='active';
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='athyperapp') THEN GRANT SELECT,INSERT,UPDATE ON control.mesh_business_partner_account_link,control.mesh_bank_account_projection,document.business_partner_bank_verification TO athyperapp;GRANT SELECT,INSERT ON control.mesh_bank_account_disclosure_inbox,snapshot.mesh_bank_account_disclosure_received TO athyperapp; END IF; END $$;
COMMIT;
